"""Editor shell: clear library actions, a spacious map and contextual properties."""
import tkinter as tk
from tkinter import ttk

BG='#111720';PANEL='#1b2432';CARD='#222e3f';TEXT='#e8eef8';MUTED='#9cabc1';ACCENT='#8399ff'

def theme(root,scale):
    style=ttk.Style(root);style.theme_use('clam');root.configure(bg=BG)
    style.configure('.',font=('Segoe UI',11),background=PANEL,foreground=TEXT)
    for name,color in [('TFrame',BG),('Panel.TFrame',PANEL),('Card.TFrame',CARD)]:style.configure(name,background=color)
    style.configure('TLabel',background=PANEL,foreground=TEXT)
    style.configure('Title.TLabel',font=('Segoe UI',18,'bold'),background=BG)
    style.configure('Sub.TLabel',font=('Segoe UI',10),background=BG,foreground=MUTED)
    style.configure('Heading.TLabel',font=('Segoe UI',12,'bold'))
    style.configure('Muted.TLabel',foreground=MUTED,font=('Segoe UI',10))
    style.configure('Card.TLabel',background=CARD)
    style.configure('TButton',padding=(10,7),background=CARD,borderwidth=0)
    style.map('TButton',background=[('active','#34445e')],foreground=[('disabled','#697991')])
    style.configure('Accent.TButton',background=ACCENT,foreground='#101629',font=('Segoe UI',11,'bold'))
    style.map('Accent.TButton',background=[('active','#a1b2ff'),('disabled','#384865')],foreground=[('disabled','#a8b3c8')])
    style.configure('Tool.TRadiobutton',padding=(9,7),background=BG)
    style.layout('Tool.TRadiobutton',[('Radiobutton.padding',{'children':[('Radiobutton.label',{'sticky':'nswe'})],'sticky':'nswe'})])
    style.map('Tool.TRadiobutton',background=[('selected','#344467'),('active',CARD)],foreground=[('selected','#d5ddff')])
    style.configure('TEntry',fieldbackground='#111b29',foreground=TEXT,insertcolor=TEXT,padding=6)
    style.configure('TCombobox',fieldbackground='#111b29',background=CARD,foreground=TEXT,padding=4,arrowsize=14)
    style.map('TCombobox',fieldbackground=[('readonly','#111b29')],foreground=[('readonly',TEXT)])
    style.configure('TNotebook',background=PANEL,borderwidth=0)
    style.configure('TNotebook.Tab',padding=(12,9),background=PANEL,foreground=MUTED)
    style.map('TNotebook.Tab',background=[('selected',CARD)],foreground=[('selected',TEXT)])
    style.configure('Treeview',background=PANEL,fieldbackground=PANEL,foreground=TEXT,borderwidth=0,rowheight=round(32*scale))
    style.map('Treeview',background=[('selected','#354b72')],foreground=[('selected','#ffffff')])
    style.configure('Sprites.Treeview',rowheight=round(82*scale));style.configure('Parts.Treeview',rowheight=round(86*scale))
    style.configure('TLabelframe',background=PANEL,borderwidth=1,relief='solid');style.configure('TLabelframe.Label',background=PANEL,foreground=MUTED)
    style.configure('TCheckbutton',background=PANEL);style.map('TCheckbutton',background=[('active',CARD)])
    style.configure('TScrollbar',background='#354157',troughcolor=BG,borderwidth=0,arrowsize=12)
    return style

def scroll_tree(parent,**options):
    frame=ttk.Frame(parent,style='Panel.TFrame');frame.pack(fill='both',expand=True)
    bar=ttk.Scrollbar(frame);bar.pack(side='right',fill='y')
    tree=ttk.Treeview(frame,show='tree',selectmode='browse',yscrollcommand=bar.set,**options)
    tree.column('#0',width=round(240*float(parent.tk.call('tk','scaling'))/(96/72)),stretch=True)
    bar.configure(command=tree.yview);tree.pack(fill='both',expand=True)
    return tree

def build(self):
    root=self.root;u=self.ui;theme(root,u)
    header=ttk.Frame(root,padding=(16,12));header.pack(fill='x')
    brand=ttk.Frame(header);brand.pack(side='left',padx=(0,24))
    ttk.Label(brand,text='CASTLEVANIA STUDIO',style='Title.TLabel').pack(anchor='w')
    ttk.Label(brand,text='Super Castlevania IV',style='Sub.TLabel').pack(anchor='w')
    project=ttk.Menubutton(header,text='Projekt ▾');project.pack(side='left',padx=4)
    menu=tk.Menu(project,tearoff=False,bg=PANEL,fg=TEXT,activebackground='#354b72')
    for title,fn in [('Neues Projekt',self.new),('Projekt öffnen…',self.open),('Speichern',self.save),('Speichern unter…',lambda:self.save(True))]:menu.add_command(label=title,command=fn)
    project.configure(menu=menu)
    ttk.Button(header,text='Öffnen',command=self.open).pack(side='left',padx=4)
    self.save_button=ttk.Button(header,text='Speichern',command=self.save);self.save_button.pack(side='left',padx=4)
    ttk.Button(header,text='↶',width=3,command=self.undo).pack(side='left',padx=(15,3))
    ttk.Button(header,text='↷',width=3,command=self.redo).pack(side='left',padx=3)
    self.stop_button=ttk.Button(header,text='■ Test beenden',command=self.stop_test);self.stop_button.pack(side='right',padx=4)
    self.test_button=ttk.Button(header,text='▶ Spieltest   F5',style='Accent.TButton',command=self.test);self.test_button.pack(side='right',padx=4)

    self.workspaces=ttk.Notebook(root);self.workspaces.pack(fill='both',expand=True,padx=4)
    self.level_page=ttk.Frame(self.workspaces);self.monster_page=ttk.Frame(self.workspaces)
    self.workspaces.add(self.level_page,text='Level & Räume');self.workspaces.add(self.monster_page,text='Monster & Animationen')
    area=self.level_page

    toolbar=ttk.Frame(area,padding=(12,8,12,10));toolbar.pack(fill='x')
    ttk.Radiobutton(toolbar,text='↖ Auswählen & ziehen',style='Tool.TRadiobutton',variable=self.tool,value='Auswahl').pack(side='left',padx=3)
    for label,key in [('＋ Gegner','Gegner'),('＋ Objekte','Objekte'),('▦ Gelände','Gelände')]:ttk.Button(toolbar,text=label,command=lambda k=key:self.open_palette(k)).pack(side='left',padx=3)
    for text,value in [('Spielerstart','Start'),('Ausgang','Ausgang')]:ttk.Radiobutton(toolbar,text=text,style='Tool.TRadiobutton',variable=self.tool,value=value).pack(side='left',padx=3)
    view=ttk.Menubutton(toolbar,text='Ansicht ▾');view.pack(side='right',padx=4)
    menu=tk.Menu(view,tearoff=False,bg=PANEL,fg=TEXT)
    for title,var in [('Vordergrund',self.show_front),('Hintergrund',self.show_back),('Kollision',self.show_collision),('Raster',self.grid),('Namen anzeigen',self.show_object_names)]:menu.add_checkbutton(label=title,variable=var,command=self.schedule)
    view.configure(menu=menu)
    z=ttk.Combobox(toolbar,textvariable=self.zoom,values=(.5,1,2,3,4),state='readonly',width=4);z.pack(side='right',padx=4);z.bind('<<ComboboxSelected>>',lambda e:self.schedule())
    ttk.Label(toolbar,text='Zoom',style='Sub.TLabel').pack(side='right',padx=(10,0))
    self.plane_label=tk.StringVar(value='Vordere Ebene')
    plane=ttk.Combobox(toolbar,textvariable=self.plane_label,values=('Vordere Ebene','Hintere Ebene'),state='readonly',width=16);plane.pack(side='right',padx=4)
    plane.bind('<<ComboboxSelected>>',lambda e:(self.layer.set('front' if self.plane_label.get()=='Vordere Ebene' else 'back'),self.palette_changed()))
    self.layer.trace_add('write',lambda *a:self.plane_label.set('Vordere Ebene' if self.layer.get()=='front' else 'Hintere Ebene'))

    self.panes=ttk.Panedwindow(area,orient='horizontal');self.panes.pack(fill='both',expand=True,padx=12)
    self.left=left=ttk.Frame(self.panes,style='Panel.TFrame',padding=10,width=round(270*u));center=ttk.Frame(self.panes,style='Panel.TFrame');right=ttk.Frame(self.panes,style='Panel.TFrame',padding=10,width=round(340*u))
    left.pack_propagate(False);right.pack_propagate(False)
    self.panes.add(left,weight=0);self.panes.add(center,weight=1);self.panes.add(right,weight=0)
    ttk.Label(left,text='Level & Räume',style='Heading.TLabel').pack(anchor='w',pady=(0,8))
    self.room_tabs=ttk.Notebook(left);self.room_tabs.pack(fill='both',expand=True)
    self.original_tab=ttk.Frame(self.room_tabs,style='Panel.TFrame');self.project_tab=ttk.Frame(self.room_tabs,style='Panel.TFrame')
    self.room_tabs.add(self.original_tab,text='Originale');self.room_tabs.add(self.project_tab,text='Mein Projekt')
    self.originals=scroll_tree(self.original_tab,height=8)
    for n in range(68):self.originals.insert('','end',iid=str(n),text=f'R-{n:02d}'+(f' · Stage 01 / A{n+1:02d}' if n<5 else ''))
    self.originals.bind('<<TreeviewSelect>>',self.choose_original)
    self.copy_original_button=ttk.Button(self.original_tab,text='Dieses Level bearbeiten',style='Accent.TButton',command=self.edit_original,state='disabled');self.copy_original_button.pack(fill='x',pady=(8,4))
    ttk.Button(self.original_tab,text='Eigenes Level beginnen',command=self.new).pack(fill='x',pady=3)
    self.rooms=scroll_tree(self.project_tab,height=8);self.rooms.bind('<<TreeviewSelect>>',self.choose_room)
    self.room_tabs.select(self.original_tab if self.original_view else self.project_tab);self.room_tabs.bind('<<NotebookTabChanged>>',self.room_tab_changed)
    self.room_controls=ttk.Frame(left,style='Panel.TFrame');self.room_controls.pack(side='bottom',fill='x',before=self.room_tabs,pady=8)
    for i,(title,fn) in enumerate([('＋ Raum',self.add_room),('Duplizieren',lambda:self.add_room(True)),('★ Startraum',self.set_start),('Eigenschaften…',self.room_dialog)]):ttk.Button(self.room_controls,text=title,command=fn).grid(row=i//2,column=i%2,sticky='ew',padx=2,pady=2)
    self.room_controls.columnconfigure((0,1),weight=1)
    ttk.Button(self.room_controls,text='Originalabschnitt hinzufügen…',command=self.import_dialog).grid(row=2,column=0,columnspan=2,sticky='ew',pady=4)
    if self.original_view:self.room_controls.pack_forget()

    banner=ttk.Frame(center,style='Card.TFrame',padding=(14,10));banner.pack(fill='x')
    self.mode_title=tk.StringVar();self.mode_hint=tk.StringVar()
    self.edit_button=ttk.Button(banner,text='Bearbeiten',style='Accent.TButton',command=self.edit_original);self.edit_button.pack(side='right',padx=(12,0))
    ttk.Label(banner,textvariable=self.mode_title,style='Card.TLabel',font=('Segoe UI',12,'bold')).pack(anchor='w')
    ttk.Label(banner,textvariable=self.mode_hint,style='Card.TLabel',wraplength=round(600*u)).pack(anchor='w',pady=(3,0))
    stage=ttk.Frame(center,style='Panel.TFrame',padding=4);stage.pack(fill='both',expand=True)
    self.canvas=tk.Canvas(stage,bg='#101722',highlightthickness=0)
    sy=ttk.Scrollbar(stage,command=self.canvas.yview);sy.pack(side='right',fill='y');sx=ttk.Scrollbar(stage,orient='horizontal',command=lambda *a:self.scroll('x',*a));sx.pack(side='bottom',fill='x')
    sy.configure(command=lambda *a:self.scroll('y',*a));self.canvas.configure(xscrollcommand=sx.set,yscrollcommand=sy.set);self.canvas.pack(fill='both',expand=True)
    self.canvas.bind('<Configure>',lambda e:self.schedule());self.canvas.bind('<Button-1>',self.press);self.canvas.bind('<B1-Motion>',self.motion);self.canvas.bind('<ButtonRelease-1>',self.release)
    self.canvas.bind('<Double-Button-1>',self.inspect_at);self.canvas.bind('<Button-3>',self.pick);self.canvas.bind('<Shift-Button-3>',self.pick_part)
    self.canvas.bind('<MouseWheel>',self.wheel);self.canvas.bind('<Button-2>',lambda e:self.canvas.scan_mark(e.x,e.y));self.canvas.bind('<B2-Motion>',self.pan)
    self.canvas.bind('<Motion>',self.hover_brush);self.canvas.bind('<Leave>',lambda e:self.hide_brush_cursor())
    self.context_hint=tk.StringVar(value='Figuren direkt anklicken und ziehen · Mittlere Maustaste: Karte verschieben')
    ttk.Label(center,textvariable=self.context_hint,style='Muted.TLabel',padding=(12,8),wraplength=round(650*u)).pack(fill='x')

    ttk.Label(right,text='Bibliothek',style='Heading.TLabel').pack(anchor='w',pady=(0,8))
    self.tabs=ttk.Notebook(right);self.tabs.pack(fill='both',expand=True)
    self.monster_tab=ttk.Frame(self.tabs,style='Panel.TFrame');self.objects_tab=ttk.Frame(self.tabs,style='Panel.TFrame');self.terrain_tab=ttk.Frame(self.tabs,style='Panel.TFrame')
    for widget,title in [(self.monster_tab,'Gegner'),(self.objects_tab,'Objekte'),(self.terrain_tab,'Gelände')]:self.tabs.add(widget,text=title)
    ttk.Label(self.monster_tab,text='Gegner suchen · Code oder Name',style='Muted.TLabel').pack(anchor='w',pady=(8,3))
    self.monster_search=ttk.Entry(self.monster_tab,textvariable=self.filter);self.monster_search.pack(fill='x',pady=(0,6));self.filter.trace_add('write',lambda *a:self.filter_monsters())
    self.monsters=scroll_tree(self.monster_tab,style='Sprites.Treeview',height=4);self.monsters.bind('<<TreeviewSelect>>',self.choose_monster)
    self.object_picker=scroll_tree(self.objects_tab,style='Sprites.Treeview',height=4);self.object_picker.bind('<<TreeviewSelect>>',self.choose_object)
    self.library_previews={};self.library_titles={};self.library_actions={}
    for kind,parent,tree in [('Monster',self.monster_tab,self.monsters),('Objekt',self.objects_tab,self.object_picker)]:
        actions=ttk.Frame(parent,style='Card.TFrame',padding=10);actions.pack(side='bottom',fill='x',pady=(8,0))
        title=tk.StringVar(value='1. Bild auswählen');self.library_titles[kind]=title
        row=ttk.Frame(actions,style='Card.TFrame');row.pack(fill='x')
        preview=tk.Canvas(row,width=round(78*u),height=round(70*u),bg=CARD,highlightthickness=0);preview.pack(side='left',padx=(0,8));self.library_previews[kind]=preview
        ttk.Label(row,textvariable=title,style='Card.TLabel',wraplength=round(180*u),font=('Segoe UI',11,'bold')).pack(side='left',fill='x',expand=True)
        add=ttk.Button(actions,text='＋ Hinzufügen',style='Accent.TButton',command=lambda k=kind:self.add_from_library(k),state='disabled');add.pack(fill='x',pady=(8,4))
        place=ttk.Button(actions,text='Mit Maus platzieren',command=lambda k=kind:self.arm_library(k),state='disabled');place.pack(fill='x')
        ttk.Label(actions,text='Oder das Bild direkt in die Karte ziehen.',style='Card.TLabel',wraplength=round(280*u)).pack(anchor='w',pady=(6,0))
        self.library_actions[kind]=(add,place)
        if kind=='Monster':ttk.Button(actions,text='Animationen & HD bearbeiten…',command=lambda:self.open_monster_workshop(self.library_entry('Monster'))).pack(fill='x',pady=(4,0))
        tree.bind('<ButtonPress-1>',lambda e,k=kind:self.library_press(e,k),add='+');tree.bind('<B1-Motion>',self.library_motion);tree.bind('<ButtonRelease-1>',self.library_release)
        tree.bind('<Double-Button-1>',lambda e,k=kind:self.add_from_library(k));tree.bind('<Return>',lambda e,k=kind:self.add_from_library(k))

    terrain=self.terrain_tab
    source=ttk.LabelFrame(terrain,text='Grafikquelle',padding=8);source.pack(fill='x',pady=6)
    from level_tiles import SOURCE_COUNT,source_name
    self.source_picker=ttk.Combobox(source,textvariable=self.source_choice,values=tuple(f'{n} · {source_name(n)}' for n in range(SOURCE_COUNT)),state='readonly');self.source_picker.pack(fill='x');self.source_picker.bind('<<ComboboxSelected>>',self.source_changed)
    layer=ttk.Combobox(source,textvariable=self.source_layer,values=('front','back'),state='readonly');layer.pack(fill='x',pady=4);layer.bind('<<ComboboxSelected>>',self.source_changed)
    for title,key in [('Pinsel','Zeichnen'),('Fläche','Fläche'),('Kollision','Kollision')]:ttk.Radiobutton(source,text=title,variable=self.tool,value=key).pack(side='left',padx=3)
    self.terrain_tabs=ttk.Notebook(terrain);self.terrain_tabs.pack(fill='both',expand=True)
    self.parts_tab=ttk.Frame(self.terrain_tabs,style='Panel.TFrame');self.terrain_tabs.add(self.parts_tab,text='Bauteile')
    from level_parts import CATEGORIES
    categories=ttk.Combobox(self.parts_tab,textvariable=self.part_category,values=CATEGORIES,state='readonly');categories.pack(fill='x',pady=4);categories.bind('<<ComboboxSelected>>',lambda e:self.refresh_parts())
    self.parts_gallery=scroll_tree(self.parts_tab,style='Parts.Treeview',height=3);self.parts_gallery.bind('<ButtonRelease-1>',self.choose_part);self.parts_gallery.bind('<Return>',self.choose_part)
    controls=ttk.Frame(self.parts_tab,style='Panel.TFrame');controls.pack(side='bottom',fill='x')
    line=ttk.Frame(controls,style='Panel.TFrame');line.pack(fill='x',pady=5);ttk.Label(line,text='Plattformlänge').pack(side='left')
    self.part_length_box=ttk.Spinbox(line,from_=1,to=32,textvariable=self.part_length,width=5,command=self.choose_part,state='disabled');self.part_length_box.pack(side='right');self.part_length_box.bind('<Return>',self.choose_part);self.part_length_box.bind('<FocusOut>',self.choose_part)
    self.brush_preview=tk.Canvas(controls,height=round(70*u),bg=CARD,highlightthickness=0);self.brush_preview.pack(fill='x');self.brush_preview.bind('<Configure>',lambda e:self.refresh_brush())
    ttk.Label(controls,textvariable=self.brush_label,wraplength=round(290*u),style='Muted.TLabel').pack(fill='x',pady=4)
    ttk.Entry(controls,textvariable=self.part_name).pack(fill='x',pady=3)
    line=ttk.Frame(controls,style='Panel.TFrame');line.pack(fill='x')
    ttk.Button(line,text='Auswahl merken',command=self.remember_selection).pack(side='left',fill='x',expand=True);ttk.Button(line,text='Pinsel merken',command=self.remember_brush).pack(side='left',fill='x',expand=True)
    ttk.Button(controls,text='Eigenes Bauteil entfernen',command=self.remove_part).pack(fill='x',pady=3)
    self.block_canvas=self.palette_canvas('Blöcke');self.tile_canvas=self.palette_canvas('Kacheln');self.block_canvas.bind('<Button-1>',self.choose_block);self.tile_canvas.bind('<Button-1>',self.choose_tile)
    collision=ttk.LabelFrame(terrain,text='Zeichenoptionen',padding=6);collision.pack(fill='x',pady=4)
    ttk.Checkbutton(collision,text='Kollision übernehmen',variable=self.auto_collision).pack(anchor='w')
    for title,value in [('Fest',1),('Frei',0)]:ttk.Radiobutton(collision,text=title,variable=self.collision,value=value).pack(side='left')
    ttk.Label(collision,text='Palette').pack(side='left',padx=(10,4));self.palette_box=ttk.Combobox(collision,textvariable=self.palette,values=tuple(range(8)),state='readonly',width=3);self.palette_box.pack(side='left');self.palette_box.bind('<<ComboboxSelected>>',lambda e:self.palette_changed())

    props=ttk.LabelFrame(left,text='Ausgewählte Figur',padding=8);self.object_props=props;self.prop_rows={}
    for n,(label,key) in enumerate([('Dein Name','name'),('X','x'),('Y','y'),('Variante','variant'),('Bewegung','motion'),('Zielraum','target'),('Ziel X','target_x'),('Ziel Y','target_y'),('Auslöser','trigger'),('Spielebene','plane')]):
        caption=ttk.Label(props,text=label);caption.grid(row=n,column=0,sticky='w',padx=(0,6))
        if key in ('target','trigger','plane','motion'):
            widget=ttk.Combobox(props,textvariable=self.props[key],width=15,state='readonly',values=('up','touch') if key=='trigger' else ('front','back') if key=='plane' else ('Waagerecht','Senkrecht') if key=='motion' else ())
            if key=='target':self.target_box=widget
            if key=='motion':self.motion_box=widget
        else:widget=ttk.Entry(props,textvariable=self.props[key],width=14)
        if key=='variant':self.variant_entry=widget
        widget.grid(row=n,column=1,sticky='ew',pady=2);self.prop_rows[key]=(caption,widget)
    props.columnconfigure(1,weight=1)
    ttk.Button(props,text='Übernehmen',command=self.apply_object).grid(row=10,column=0,columnspan=2,sticky='ew',pady=4)
    ttk.Label(props,textvariable=self.actor_stats,wraplength=round(240*u),style='Muted.TLabel').grid(row=11,column=0,columnspan=2,sticky='w')
    self.details_button=ttk.Button(props,text='Werte / KI / Boss…',command=self.actor_details);self.details_button.grid(row=12,column=0,columnspan=2,sticky='ew',pady=5)
    self.animation_button=ttk.Button(props,text='Animationen & HD…',command=self.open_monster_workshop);self.animation_button.grid(row=14,column=0,columnspan=2,sticky='ew',pady=4)
    self.duplicate_button=ttk.Button(props,text='Duplizieren',command=self.duplicate_actor);self.duplicate_button.grid(row=13,column=0,sticky='ew');ttk.Button(props,text='Löschen',command=self.delete).grid(row=13,column=1,sticky='ew')
    self.tabs.bind('<<NotebookTabChanged>>',self.part_tab_changed);self.terrain_tabs.bind('<<NotebookTabChanged>>',self.part_tab_changed)
    ttk.Label(area,textvariable=self.status,style='Sub.TLabel',padding=(16,10),wraplength=round(1450*u)).pack(fill='x')
    for key,fn in [('<Control-s>',self.save),('<Control-o>',self.open),('<Control-n>',self.new),('<Control-z>',self.undo),('<Control-y>',self.redo),('<F5>',self.test),('<Escape>',self.cancel_placement)]:root.bind(key,lambda e,f=fn:f())
    for key,fn in [('<Control-c>',self.copy),('<Control-v>',self.paste),('<Delete>',self.delete)]:self.canvas.bind(key,lambda e,f=fn:f())
    for key,delta in [('Left',(-1,0)),('Right',(1,0)),('Up',(0,-1)),('Down',(0,1))]:
        self.canvas.bind('<'+key+'>',lambda e,d=delta:self.nudge_actor(*d));self.canvas.bind('<Shift-'+key+'>',lambda e,d=delta:self.nudge_actor(d[0]*8,d[1]*8))
    self.canvas.bind('<h>',lambda e:self.flip(True));self.canvas.bind('<v>',lambda e:self.flip(False));root.protocol('WM_DELETE_WINDOW',self.close)
    self.tool.trace_add('write',lambda *a:self.mode_changed())
